using System.Diagnostics;
using Keynote.Core;
using Keynote.Playback;
namespace Keynote.Tests;
public class PlaybackTests {
 static MidiNote N(int pitch,int start,int length)=>new(pitch,100,TimeSpan.FromMilliseconds(start),TimeSpan.FromMilliseconds(length),0);
 static MidiSong Song(params MidiNote[] n)=>new("test",new[]{new MidiTrack(0,n)});
 static KeyboardMapping Map()=>new(){Keys=new(){{60,"A"},{62,"S"}}};
 sealed class Fake : IKeyboardInput {
  readonly object gate=new(); readonly List<string> events=new(); readonly HashSet<string> held=new(); public volatile bool Focus=true; public bool FailPress; public string? FailKey; public bool IsTargetForeground=>Focus;
  public string[] Events { get { lock(gate)return events.ToArray(); } } public string[] Held { get { lock(gate)return held.ToArray(); } }
  public void Press(string key) { lock(gate) { if(!Focus) throw new InvalidOperationException("focus"); if(FailPress || key==FailKey) throw new InvalidOperationException("press failed"); held.Add(key); events.Add("+"+key); } }
  public void Release(string key) { lock(gate) { if(held.Remove(key)) events.Add("-"+key); } }
  public void ReleaseAll() { lock(gate) { foreach(var k in held.ToArray()) { events.Add("-"+k); held.Remove(k); } } }
  public void Dispose()=>ReleaseAll();
 }
 static async Task WaitFor(Func<bool> condition) { var sw=Stopwatch.StartNew(); while(!condition()) { if(sw.Elapsed>TimeSpan.FromSeconds(3)) throw new TimeoutException("Playback did not reach expected state."); await Task.Delay(5); } }
 [Fact] public async Task ChordAndRepeatedNotesHaveOrderedEdges() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,80),N(62,0,80),N(60,80,80)),Map()); await WaitFor(()=>engine.State==PlaybackState.Stopped); Assert.Equal(new[]{"+A","+S","-A","-S","+A","-A"},fake.Events); }
 [Fact] public async Task OverlapRetainsKeyUntilLastNoteEnds() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,140),N(60,50,160)),Map()); await WaitFor(()=>engine.State==PlaybackState.Stopped); Assert.Equal(new[]{"+A","-A"},fake.Events); }
 [Fact] public async Task PauseReleasesThenResumeRestoresActiveNotesAndFreezesTime() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,500)),Map()); await WaitFor(()=>fake.Held.Length==1); engine.Pause(); Assert.Empty(fake.Held); var pos=engine.Position; await Task.Delay(100); Assert.InRange((engine.Position-pos).Duration().TotalMilliseconds,0,5); engine.Resume(); Assert.Equal(new[]{"A"},fake.Held); await engine.StopAsync(); Assert.Empty(fake.Held); Assert.Equal(new[]{"+A","-A","+A","-A"},fake.Events); }
 [Fact] public async Task SpeedChangePreservesElapsedPosition() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,1000)),Map()); await WaitFor(()=>fake.Held.Length==1); await Task.Delay(70); var before=engine.Position; engine.Speed=2; var after=engine.Position; Assert.InRange((after-before).TotalMilliseconds,0,30); await Task.Delay(80); var gain=(engine.Position-after).TotalMilliseconds; Assert.InRange(gain,110,300); await engine.StopAsync(); }
 [Fact] public async Task StopCancelsLongWaitAndAllowsNewPlayback() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,2000,100)),Map()); Assert.Throws<InvalidOperationException>(()=>engine.Start(Song(N(60,0,10)),Map())); var sw=Stopwatch.StartNew(); await engine.StopAsync(); Assert.True(sw.ElapsedMilliseconds<500); Assert.Empty(fake.Events); engine.Start(Song(N(62,0,20)),Map()); await WaitFor(()=>engine.State==PlaybackState.Stopped); Assert.Equal(new[]{"+S","-S"},fake.Events); }
 [Fact] public async Task StopWhilePausedNeverRetriggersNotes() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,1000)),Map()); await WaitFor(()=>fake.Held.Length==1); engine.Pause(); await engine.StopAsync(); engine.Resume(); Assert.Equal(new[]{"+A","-A"},fake.Events); Assert.Equal(PlaybackState.Stopped,engine.State); }
 [Fact] public async Task ResumeCannotRetriggerAfterStopHasBeenRequested() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,1000)),Map()); await WaitFor(()=>fake.Held.Length==1); engine.Pause(); var stopping=engine.StopAsync(); engine.Resume(); await stopping; Assert.Equal(new[]{"+A","-A"},fake.Events); Assert.Empty(fake.Held); }
 [Fact] public async Task FocusLossStopsAndReleases() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,500)),Map()); await WaitFor(()=>fake.Held.Length==1); fake.Focus=false; await WaitFor(()=>engine.State==PlaybackState.Paused); Assert.Empty(fake.Held); Assert.Contains("focus",engine.Error!,StringComparison.OrdinalIgnoreCase); Assert.Equal(1,engine.Diagnostics.FocusLosses); fake.Focus=true; engine.Resume(); Assert.Equal(PlaybackState.Playing,engine.State); await engine.StopAsync(); }
 [Fact] public async Task PausedOnFocusLossCannotResumeUntilFocusReturns() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,500)),Map()); await WaitFor(()=>fake.Held.Length==1); fake.Focus=false; await WaitFor(()=>engine.State==PlaybackState.Paused); var position=engine.Position; engine.Resume(); Assert.Equal(PlaybackState.Paused,engine.State); Assert.Empty(fake.Held); await Task.Delay(50); Assert.InRange((engine.Position-position).Duration().TotalMilliseconds,0,5); fake.Focus=true; engine.Resume(); Assert.Equal(PlaybackState.Playing,engine.State); Assert.Equal(new[]{"A"},fake.Held); await engine.StopAsync(); }
 [Fact] public async Task DiagnosticsCountScheduledAndDispatchedEvents() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,40),N(62,0,40)),Map()); await WaitFor(()=>engine.State==PlaybackState.Stopped); var d=engine.Diagnostics; Assert.Equal(4,d.Scheduled); Assert.Equal(4,d.Dispatched); Assert.Equal(0,d.Failed); Assert.InRange(d.AverageLateMs,0,d.MaxLateMs); }
 [Fact] public async Task InputExceptionFaultsWithoutStuckKeys() { var fake=new Fake { FailPress=true }; using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,100)),Map()); await WaitFor(()=>engine.State==PlaybackState.Faulted); Assert.Empty(fake.Held); Assert.Contains("press failed",engine.Error); }
 [Fact] public async Task FailureMidChordReleasesPreviouslyPressedKeys() { var fake=new Fake { FailKey="S" }; using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,500),N(62,0,500)),Map()); await WaitFor(()=>engine.State==PlaybackState.Faulted); Assert.Empty(fake.Held); Assert.Equal(new[]{"+A","-A"},fake.Events); }
 [Fact] public async Task DisposeReleasesActiveNotes() { var fake=new Fake(); var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,5000)),Map()); await WaitFor(()=>fake.Held.Length==1); engine.Dispose(); Assert.Empty(fake.Held); Assert.Equal(new[]{"+A","-A"},fake.Events); }
 [Fact] public void StartValidatesFocusAndMappingsBeforeSending() { var fake=new Fake { Focus=false }; using var engine=new PlaybackEngine(fake); Assert.Throws<InvalidOperationException>(()=>engine.Start(Song(N(60,0,100)),Map())); fake.Focus=true; var map=Map(); map.Keys[60]="Ctrl+A"; Assert.Throws<InvalidOperationException>(()=>engine.Start(Song(N(60,0,100)),map)); Assert.Empty(fake.Events); }
 [Fact] public async Task SeekPausesAndReleasesThenRestoresOnlyNotesAtDestination() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,1000),N(62,500,1000)),Map()); await WaitFor(()=>fake.Held.Contains("A")); engine.Seek(TimeSpan.FromMilliseconds(750)); Assert.Equal(PlaybackState.Paused,engine.State); Assert.Empty(fake.Held); Assert.Equal(TimeSpan.FromMilliseconds(750),engine.Position); engine.Resume(); Assert.Equal(new[]{"A","S"},fake.Held.Order().ToArray()); await engine.StopAsync(); Assert.Empty(fake.Held); }
 [Fact] public async Task SeekBackwardRebuildsOverlappingNoteCounts() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,250),N(60,100,450)),Map()); await WaitFor(()=>fake.Held.Contains("A")); engine.Seek(TimeSpan.FromMilliseconds(150)); engine.Resume(); await Task.Delay(150); Assert.Equal(new[]{"A"},fake.Held); await WaitFor(()=>engine.State==PlaybackState.Stopped); Assert.Empty(fake.Held); }
 [Fact] public async Task StartAtPositionRestoresSustainedNotesAndReleasesThem() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,400),N(62,200,350)),Map(),startPosition:TimeSpan.FromMilliseconds(250)); Assert.Equal(new[]{"A","S"},fake.Held.Order().ToArray()); await WaitFor(()=>engine.State==PlaybackState.Stopped); Assert.Empty(fake.Held); }
 [Fact] public async Task SeekToNoteEndDoesNotRetriggerEndedNote() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,300),N(62,500,200)),Map()); await WaitFor(()=>fake.Held.Contains("A")); engine.Seek(TimeSpan.FromMilliseconds(300)); Assert.Empty(fake.Held); engine.Resume(); Assert.Empty(fake.Held); await engine.StopAsync(); Assert.Equal(new[]{"+A","-A"},fake.Events); }
 [Fact] public async Task SeekWhilePausedNeverInjectsWithoutForeground() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,1000)),Map()); await WaitFor(()=>fake.Held.Length==1); fake.Focus=false; await WaitFor(()=>engine.State==PlaybackState.Paused); engine.Seek(TimeSpan.FromMilliseconds(500)); engine.Resume(); Assert.Empty(fake.Held); Assert.Equal(PlaybackState.Paused,engine.State); await engine.StopAsync(); }
 [Fact] public async Task SeekRejectsOutOfRangeAndStoppedSessions() { var fake=new Fake(); using var engine=new PlaybackEngine(fake); engine.Start(Song(N(60,0,500)),Map()); Assert.Throws<ArgumentOutOfRangeException>(()=>engine.Seek(TimeSpan.FromMilliseconds(501))); await engine.StopAsync(); Assert.Throws<InvalidOperationException>(()=>engine.Seek(TimeSpan.Zero)); Assert.Empty(fake.Held); }
 [Fact] public void SpeedRejectsNonFiniteValues() { using var engine=new PlaybackEngine(new Fake()); Assert.Throws<ArgumentOutOfRangeException>(()=>engine.Speed=double.NaN); }
}
